engine.parseOarsFields:
function parseOarsFields(text) {
  if (!text) return {};
  var lines = String(text).split(/\r?\n/);
  var startIdx = 0;
  for (var i = 0; i < lines.length; i++) {
    if (/\bOARS\b/i.test(lines[i])) { startIdx = i; break; }
  }
  var fields = {};
  var stop = false;
  for (var j = startIdx; j < lines.length && !stop; j++) {
    var ln = lines[j].trim();
    if (!ln) { if (Object.keys(fields).length) stop = true; continue; }
    var m = ln.match(/^([A-Za-z][A-Za-z0-9 _\-]+?)\s*[:=]\s*(.+)$/);
    if (m) fields[m[1].trim()] = m[2].trim();
  }
  return fields;
}

// Truncate a filename for chip display. Mirrors v2 chip behavior:
// names over 18 chars get the first 15 + ellipsis. Used by both the
// chip render and the viewer dialog header.

engine.truncateLabel:
function truncateLabel(name) {
  if (!name) return "";
  var s = String(name);
  return s.length > 18 ? (s.slice(0, 15) + "…") : s;
}

// Engine entry — convenience wrapper for callers that want one call
// to shape both fields + label. Self-contained: helpers inlined.

engine.analyze:
function analyze(input, providers) {
  // Inline: parseOarsFields
  var fields = {};
  var text = String((input && input.text) || "");
  if (text) {
    var lines = text.split(/\r?\n/);
    var startIdx = 0;
    for (var i = 0; i < lines.length; i++) {
      if (/\bOARS\b/i.test(lines[i])) { startIdx = i; break; }
    }
    var stop = false;
    for (var j = startIdx; j < lines.length && !stop; j++) {
      var ln = lines[j].trim();
      if (!ln) { if (Object.keys(fields).length) stop = true; continue; }
      var m = ln.match(/^([A-Za-z][A-Za-z0-9 _\-]+?)\s*[:=]\s*(.+)$/);
      if (m) fields[m[1].trim()] = m[2].trim();
    }
  }
  // Inline: truncateLabel
  var name = String((input && input.name) || "OARS DATA");
  var label = name.length > 18 ? (name.slice(0, 15) + "…") : name;
  return Promise.resolve({
    fields: fields,
    label: label,
    fieldCount: Object.keys(fields).length,
    provenance: {
      kernelVersion: (window.eli && window.eli.kernelVersion) || "unknown",
      toolVersion: "0.1",
      docHash: "h" + (text.length || 0),
      timestamp: Date.now(),
    },
  });
}

view.renderChip:
function renderChip(opts) {
  var mount = opts.mount;
  if (!mount) return null;
  var loaded = opts.state || null;
  var processing = !!opts.processing;
  var wrap = document.createElement("span");
  wrap.className = "_eli3_status_data" + (loaded ? " _eli3_status_data_loaded" : "");
  wrap.id = "_eli3_status_data";

  var pill = document.createElement("label");
  pill.className = "_eli3_status_data_pill";
  pill.htmlFor = "_eli3_status_data_input";
  pill.title = loaded ? "OARS data loaded — click to upload a different file" : "Upload OARS data";

  var icon = document.createElement("span");
  icon.className = "_eli3_status_data_icon";
  if (loaded) {
    icon.classList.add("_eli3_status_data_icon_loaded");
    icon.textContent = "⚡";
    icon.title = "View OARS data (processed / unprocessed)";
    icon.onclick = function (e) {
      e.preventDefault(); e.stopPropagation();
      if (typeof opts.onShowViewer === "function") opts.onShowViewer();
    };
  } else if (processing) {
    icon.classList.add("_eli3_status_data_icon_processing");
    icon.textContent = "⏳";
    icon.title = "Processing OARS data…";
  } else {
    icon.classList.add("_eli3_status_data_icon_empty");
    icon.textContent = "📂";
    icon.title = "No OARS data — click to upload";
  }
  pill.appendChild(icon);

  var txt = document.createElement("span");
  txt.className = "_eli3_status_data_text";
  txt.textContent = loaded ? loaded.label : "DATA";
  if (loaded) txt.classList.add("_eli3_status_data_text_loaded");
  pill.appendChild(txt);
  wrap.appendChild(pill);

  if (loaded) {
    var clear = document.createElement("span");
    clear.className = "_eli3_status_data_clear";
    clear.title = "Clear loaded data";
    clear.textContent = "✕";
    clear.onclick = function (e) {
      e.preventDefault(); e.stopPropagation();
      if (typeof opts.onClear === "function") opts.onClear();
    };
    wrap.appendChild(clear);
  }

  var input = document.createElement("input");
  input.type = "file";
  input.id = "_eli3_status_data_input";
  input.style.display = "none";
  input.accept = ".docx,.txt,.json,.csv,application/pdf";
  input.onchange = function () {
    var f = input.files && input.files[0];
    if (!f) return;
    if (typeof opts.onPickFile === "function") opts.onPickFile(f);
    input.value = "";
  };
  wrap.appendChild(input);
  mount.appendChild(wrap);
  return wrap;
}

// Tabbed viewer dialog — Processed (parsed fields grid) + Unprocessed
// (raw text). opts: { text, fields: {key: value}, name }

view.renderViewer:
function renderViewer(opts) {
  // Inline _esc — bundle isolation safety.
  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  var fields = opts.fields || {};
  var fieldKeys = Object.keys(fields);
  var text = String(opts.text || "");
  var processedHtml = fieldKeys.length
    ? '<div class="_eli3_oars_viewer_grid">' +
        fieldKeys.map(function (k) {
          return '<div class="_eli3_oars_viewer_k">' + _esc(k) + '</div>' +
                 '<div class="_eli3_oars_viewer_v">' + _esc(fields[k]) + '</div>';
        }).join("") +
      '</div>'
    : '<div class="_eli3_oars_viewer_empty">No structured fields parsed.</div>';
  var unprocessedHtml = '<pre class="_eli3_oars_viewer_pre">' + _esc(text) + '</pre>';
  var bodyHtml =
    '<div class="_eli3_oars_viewer_tabs">' +
      '<button class="_eli3_oars_viewer_tab _eli3_oars_viewer_tab_active" data-tab="processed">Processed (' + fieldKeys.length + ')</button>' +
      '<button class="_eli3_oars_viewer_tab" data-tab="unprocessed">Unprocessed</button>' +
    '</div>' +
    '<div class="_eli3_oars_viewer_panel" data-panel="processed">' + processedHtml + '</div>' +
    '<div class="_eli3_oars_viewer_panel _eli3_oars_viewer_panel_hidden" data-panel="unprocessed">' + unprocessedHtml + '</div>';
  if (typeof showEliDialog !== "function") return null;
  return showEliDialog({
    variant: "info",
    tier: "premium",
    dialogClass: "_eli3_dialog_wide _eli3_oars_viewer_dialog",
    icon: "⚡",
    title: "OARS Data Viewer",
    body: bodyHtml,
    draggable: true,
    resizable: true,
    secondary: { label: "Close" },
    onMount: function (overlay) {
      overlay.querySelectorAll("._eli3_oars_viewer_tab").forEach(function (btn) {
        btn.onclick = function () {
          overlay.querySelectorAll("._eli3_oars_viewer_tab").forEach(function (b) {
            b.classList.toggle("_eli3_oars_viewer_tab_active", b === btn);
          });
          var which = btn.getAttribute("data-tab");
          overlay.querySelectorAll("._eli3_oars_viewer_panel").forEach(function (p) {
            p.classList.toggle("_eli3_oars_viewer_panel_hidden", p.getAttribute("data-panel") !== which);
          });
        };
      });
    },
  });
}

// Full-screen overlay shown during the boot-time auto-launch flash.
// FROM v2 lines 23858+ (_eliShowOarsOverlay). Returns { remove } so
// init.js can dismiss it on the oars:ready bus signal.

view.renderOverlay:
function renderOverlay() {
  if (document.getElementById("_eli3_oars_overlay")) {
    return { remove: function () {} };
  }
  var div = document.createElement("div");
  div.id = "_eli3_oars_overlay";
  div.style.cssText =
    "position:fixed;top:0;left:0;width:100%;height:100%;" +
    "background:rgba(255,255,255,0.95);z-index:99999;" +
    "display:flex;flex-direction:column;align-items:center;justify-content:center;";
  div.innerHTML =
    '<div style="width:50px;height:50px;border:5px solid #1565c0;border-right-color:transparent;border-radius:50%;animation:_eli3_oars_spin 1s linear infinite"></div>' +
    '<div style="font:700 20px/1.2 Georgia,serif;color:#1565c0;margin-top:25px">Importing data from OARS…</div>' +
    '<div style="font:400 12px/1 Inter,sans-serif;color:#546e7a;margin-top:8px">Analyzing active document</div>' +
    '<style>@keyframes _eli3_oars_spin{from{transform:rotate(0)}to{transform:rotate(360deg)}}</style>';
  document.body.appendChild(div);
  return {
    remove: function () {
      var el = document.getElementById("_eli3_oars_overlay");
      if (!el) return;
      el.style.transition = "opacity .5s";
      el.style.opacity = "0";
      setTimeout(function () { if (el.parentNode) el.parentNode.removeChild(el); }, 500);
    },
  };
}

jsonTools.init:
function init(eli) {
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };
  var bundle = eli.tools._loaded["oars_loader"];
  if (!bundle) return;
  var efns = bundle._eliEngineFns || {};
  var vfns = bundle._eliViewFns || {};
  var parseOarsFields = efns.parseOarsFields;
  var truncateLabel = efns.truncateLabel;
  var renderChip = vfns.renderChip;
  var renderViewer = vfns.renderViewer;
  var renderOverlay = vfns.renderOverlay;
  if (!renderChip || !renderViewer) {
    eli.log.event("tool", "oars_loader_load_failed", {
      hasChip: !!renderChip, hasViewer: !!renderViewer,
    });
    return;
  }

  // ─── Office settings I/O ─────────────────────────────────────────
  // Per-doc state. Survives reload + share + copy. Sentinel
  // "OarsUserCleared" is sticky — users opt back in via fresh upload.

  function _settings() {
    try {
      return (window.Office && Office.context && Office.context.document && Office.context.document.settings) || null;
    } catch (e) { return null; }
  }

  function _getState() {
    var s = _settings();
    if (!s) return null;
    try {
      var cleared = s.get("OarsUserCleared");
      if (cleared === true || cleared === "1" || cleared === "true") return null;
      var text = s.get("AgreementDataText");
      if (!text) return null;
      var name = s.get("AgreementDataName") || "OARS DATA";
      var source = s.get("AgreementDataSource") || "file";
      var label = name.length > 18 ? (name.slice(0, 15) + "…") : name;
      return { label: label, name: name, size: (typeof text === "string" ? text.length : 0), source: source, text: text };
    } catch (e) { return null; }
  }

  function _persist(name, text, source) {
    var s = _settings();
    if (!s) return Promise.resolve(false);
    try {
      if (name) s.set("AgreementDataName", name);
      if (text) s.set("AgreementDataText", text);
      s.set("AgreementDataSource", source || "file");
      try { s.remove("OarsUserCleared"); } catch (e) {}
      return new Promise(function (resolve) { s.saveAsync(function () { resolve(true); }); });
    } catch (e) { return Promise.resolve(false); }
  }

  function _unpersist() {
    var s = _settings();
    if (!s) return Promise.resolve(false);
    try {
      ["AgreementDataName", "AgreementDataText", "AgreementDataSource",
       "AgreementDataType", "AgreementDataDetails",
       "BuildDraftTemplateLoaded"].forEach(function (k) {
        try { s.remove(k); } catch (e) {}
      });
      try { s.set("OarsUserCleared", "1"); } catch (e) {}
      return new Promise(function (resolve) {
        s.saveAsync(function (res) {
          var ok = res && res.status === Office.AsyncResultStatus.Succeeded;
          eli.log.event("oars", "user_cleared_saved", {
            ok: !!ok,
            code: res && res.error && res.error.code,
            msg: res && res.error && res.error.message,
          });
          if (!ok && typeof showToast === "function") {
            showToast("Clear saved in memory but disk persist failed — try again", "warn");
          }
          resolve(!!ok);
        });
      });
    } catch (e) {
      eli.log.event("oars", "user_cleared_threw", { msg: e && e.message });
      return Promise.resolve(false);
    }
  }

  function _isTemplateLoaded() {
    var s = _settings();
    if (!s) return false;
    try { return s.get("BuildDraftTemplateLoaded") === true; }
    catch (e) { return false; }
  }
  function _setTemplateLoaded(loaded) {
    var s = _settings();
    if (!s) return Promise.resolve(false);
    try {
      if (loaded) s.set("BuildDraftTemplateLoaded", true);
      else { try { s.remove("BuildDraftTemplateLoaded"); } catch (e) {} }
      return new Promise(function (resolve) { s.saveAsync(function () { resolve(true); }); });
    } catch (e) { return Promise.resolve(false); }
  }

  // ─── Footer slot render ──────────────────────────────────────────

  var _processing = false;

  function _paintChip(mount) {
    var state = _getState();
    renderChip({
      mount: mount,
      state: state,
      processing: _processing,
      onPickFile: _handleFile,
      onShowViewer: _showViewer,
      onClear: _clear,
    });
  }

  function _refreshChip() {
    if (eli.dashboard && typeof eli.dashboard.refreshFooter === "function") {
      eli.dashboard.refreshFooter();
    }
  }

  // ─── File upload + parse ─────────────────────────────────────────

  function _handleFile(file) {
    var ext = (file.name.split(".").pop() || "").toLowerCase();
    _processing = true;
    _refreshChip();
    var reader = new FileReader();
    function _emit(text, source) {
      _processing = false;
      // Persist FIRST so the redraw reads the updated settings.
      _persist(file.name, text, source || "file");
      _setTemplateLoaded(false);
      _refreshChip();
      eli.bus.emit("oars:file_selected", {
        name: file.name, size: file.size, text: text, source: source || "file",
      });
      eli.log.event("oars", "uploaded", { name: file.name, size: file.size, ext: ext });
      if (typeof showToast === "function") {
        var label = file.name.length > 18 ? (file.name.slice(0, 15) + "…") : file.name;
        showToast("📁 " + label + " loaded", "ok");
      }
    }
    function _onError(msg) {
      _processing = false;
      _refreshChip();
      if (typeof showToast === "function") showToast(msg, "err");
    }
    if (ext === "docx" && typeof window.mammoth !== "undefined" && window.mammoth.extractRawText) {
      reader.onload = function () {
        window.mammoth.extractRawText({ arrayBuffer: reader.result })
          .then(function (r) { _emit((r && r.value) || "", "file"); })
          .catch(function (err) {
            _onError("Couldn't parse " + file.name + ": " + (err && err.message || "unknown"));
          });
      };
      reader.readAsArrayBuffer(file);
    } else {
      reader.onload = function () { _emit(String(reader.result || ""), "file"); };
      reader.readAsText(file);
    }
    reader.onerror = function () { _onError("Couldn't read " + file.name); };
  }

  // Body-scan path — called when boot finds OARS in the doc text.
  function _setFromBody(name, text) {
    _persist(name, text, "body");
    _setTemplateLoaded(false);
    _refreshChip();
    eli.bus.emit("oars:file_selected", {
      name: name, size: text.length, text: text, source: "body",
    });
  }

  function _clear() {
    if (typeof showToast === "function") showToast("🗑️ Clearing OARS data…", "info");
    var savePromise = _unpersist();
    _refreshChip();
    eli.bus.emit("oars:cleared", {});
    eli.log.event("oars", "cleared", {});
    savePromise.then(function (ok) {
      if (typeof showToast === "function") {
        showToast(ok ? "🗑️ OARS data cleared" : "Clear partial — reload to retry", ok ? "ok" : "warn");
      }
    });
  }

  // ─── Viewer ──────────────────────────────────────────────────────

  function _showViewer() {
    var st = _getState();
    if (!st || !st.text) {
      if (typeof showToast === "function") showToast("No OARS data loaded.", "warn");
      return;
    }
    var fields = parseOarsFields ? parseOarsFields(st.text) : {};
    renderViewer({ text: st.text, fields: fields, name: st.name });
  }

  // ─── Boot-time body scan + auto-launch ───────────────────────────
  // FROM v2 _eliCheckOarsAndLaunch (lines 23858-23913). Runs after
  // boot:complete so build_draft + other listeners are wired before
  // we emit oars:detected.

  function _flashAndLaunch() {
    if (!renderOverlay) return;
    var overlayCtrl = renderOverlay();
    var fallback = setTimeout(function () {
      eli.log.event("oars", "ready_timeout", {});
      overlayCtrl.remove();
    }, 30000);
    if (eli.bus && typeof eli.bus.once === "function") {
      eli.bus.once("oars:ready", function () {
        clearTimeout(fallback);
        overlayCtrl.remove();
      });
    } else {
      clearTimeout(fallback);
      setTimeout(function () { overlayCtrl.remove(); }, 1500);
    }
    try {
      eli.bus.emit("oars:detected", { ts: Date.now() });
      var handler = eli.get && eli.get("tile", "app_build_draft");
      if (typeof handler === "function") handler();
    } catch (e) { eli.log.event("oars", "dispatch_failed", { msg: e && e.message }); }
  }

  function _restoreFromDoc() {
    var s = _settings();
    if (!s) return null;
    try {
      var name = s.get("AgreementDataName");
      var text = s.get("AgreementDataText");
      var source = s.get("AgreementDataSource") || "file";
      if (!text) return null;
      return { name: name || "OARS DATA", text: text, source: source };
    } catch (e) { return null; }
  }

  function _checkAndLaunch() {
    if (typeof Word === "undefined" || !Word.run) return;
    // User-cleared sticky bail-out.
    var s = _settings();
    if (s) {
      try {
        var sentinel = s.get("OarsUserCleared");
        var isCleared = sentinel === true || sentinel === "1" || sentinel === "true" ||
          (typeof sentinel === "string" && sentinel.length > 0);
        eli.log.event("oars", "sentinel_check", {
          raw: sentinel, type: typeof sentinel, isCleared: isCleared,
        });
        if (isCleared) {
          eli.log.event("oars", "user_cleared_skip", {});
          return;
        }
      } catch (e) { /* tolerate */ }
    }
    // Already-converted: silent restore, no overlay.
    if (_isTemplateLoaded()) {
      var saved = _restoreFromDoc();
      if (saved && saved.text) {
        _refreshChip();
        eli.bus.emit("oars:file_selected", {
          name: saved.name, size: saved.text.length, text: saved.text, source: saved.source,
        });
      }
      eli.log.event("oars", "template_already_loaded", {});
      return;
    }
    // 1. Try settings restore (saved from prior session).
    var restored = _restoreFromDoc();
    if (restored && restored.text) {
      eli.log.event("oars", "restored_from_settings", {});
      _refreshChip();
      eli.bus.emit("oars:file_selected", {
        name: restored.name, size: restored.text.length, text: restored.text, source: restored.source,
      });
      _flashAndLaunch();
      return;
    }
    // 2. Fresh body scan.
    Word.run(function (context) {
      var body = context.document.body;
      body.load("text");
      return context.sync().then(function () {
        var txt = body.text || "";
        return { hit: /\bOARS\b/i.test(txt), text: txt };
      });
    }).then(function (res) {
      if (!res || !res.hit) return;
      _setFromBody("OARS DATA", res.text);
      _flashAndLaunch();
    }).catch(function (e) {
      eli.log.event("oars", "scan_failed", { msg: e && e.message });
    });
  }

  // ─── Slot + channels + boot hook ─────────────────────────────────

  if (eli.dashboard && typeof eli.dashboard.registerFooterSlot === "function") {
    eli.dashboard.registerFooterSlot("oars_loader", function (opts) {
      _paintChip(opts.mount);
    }, { region: "left", order: 10 });
  }

  eli.register({
    oars: {
      getState: function () { return _getState(); },
      getTemplate: function () { return _getState(); },
      isTemplateLoaded: function () { return _isTemplateLoaded(); },
      setTemplateLoaded: function (v) { return _setTemplateLoaded(v); },
      showViewer: _showViewer,
      clear: _clear,
      setFromBody: function (payload) {
        if (!payload || !payload.text) return;
        _setFromBody(payload.name || "OARS DATA", payload.text);
      },
    },
    tile: { app_oars_loader: _showViewer },
  });

  // Legacy localStorage cleanup — one-shot delete of v2-era cache key.
  try {
    if (eli.compat && typeof eli.compat.lsRemove === "function") {
      eli.compat.lsRemove("_eli3_oars_loaded");
    }
  } catch (e) { /* tolerate */ }

  // Run the body scan after boot completes so build_draft + other
  // listeners are wired before we emit oars:detected.
  if (eli.bus && typeof eli.bus.on === "function") {
    eli.bus.on("boot:complete", function () {
      try { _checkAndLaunch(); }
      catch (e) { eli.log.event("oars", "check_threw", { msg: e && e.message }); }
    });
  }

  eli.log.event("tool", "oars_loader_initialized", {});
}
